source='"""Single-process Linux resource guard; only signals its own child process group."""\nimport argparse\nfrom datetime import datetime, timezone\nimport json\nimport os\nfrom pathlib import Path\nimport signal\nimport subprocess\nimport sys\nimport time\n\n\ndef write(path,value):\n    tmp=path.with_suffix(\'.tmp\')\n    tmp.write_text(json.dumps(value,indent=2)+\'\\n\',encoding=\'utf8\')\n    tmp.replace(path)\n\n\ndef rss_tree(root):\n    pending=[root]\n    total=0\n    seen=set()\n    while pending:\n        pid=pending.pop()\n        if pid in seen:\n            continue\n        seen.add(pid)\n        try:\n            status=Path(f\'/proc/{pid}/status\').read_text()\n            for line in status.splitlines():\n                if line.startswith(\'VmRSS:\'):\n                    total+=int(line.split()[1])*1024\n            children=Path(f\'/proc/{pid}/task/{pid}/children\').read_text().split()\n            pending.extend(map(int,children))\n        except (FileNotFoundError,ProcessLookupError):\n            pass\n    return total,sorted(seen)\n\n\ndef main():\n    parser=argparse.ArgumentParser()\n    parser.add_argument(\'--output\',required=True)\n    parser.add_argument(\'--rss-limit-gib\',type=float,default=48.)\n    parser.add_argument(\'command\',nargs=argparse.REMAINDER)\n    args=parser.parse_args()\n    out=Path(args.output)\n    out.mkdir(parents=True,exist_ok=True)\n    command=args.command[1:] if args.command and args.command[0]==\'--\' else args.command\n    if not command:\n        raise ValueError(\'missing child command\')\n    import fcntl\n    lock=(out/\'run.lock\').open(\'a\')\n    fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n    with (out/\'console.log\').open(\'a\',buffering=1) as log:\n        child=subprocess.Popen(command,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)\n        try:\n            started=datetime.now(timezone.utc).isoformat()\n            write(out/\'launch.json\',dict(supervisor_pid=os.getpid(),child_pid=child.pid,command=command,started_utc=started))\n            peak=0\n            reason=None\n            while child.poll() is None:\n                rss,pids=rss_tree(child.pid)\n                peak=max(peak,rss)\n                receipt=dict(supervisor_pid=os.getpid(),child_pid=child.pid,rss_bytes=rss,\n                    peak_rss_bytes=peak,child_tree=pids,utc=datetime.now(timezone.utc).isoformat())\n                write(out/\'resource_status.json\',receipt)\n                if rss>args.rss_limit_gib*1024**3:\n                    reason=\'owned_child_RSS_limit_exceeded\'\n                    os.killpg(child.pid,signal.SIGTERM)\n                    try:\n                        child.wait(timeout=20)\n                    except subprocess.TimeoutExpired:\n                        os.killpg(child.pid,signal.SIGKILL)\n                    break\n                time.sleep(1)\n            code=child.wait()\n            write(out/\'exit_receipt.json\',dict(exit_code=code,reason=reason,peak_rss_bytes=peak,\n                started_utc=started,ended_utc=datetime.now(timezone.utc).isoformat(),\n                supervisor_pid=os.getpid(),child_pid=child.pid))\n            sys.exit(code if code>=0 else 1)\n        finally:\n            if child.poll() is None:\n                os.killpg(child.pid,signal.SIGTERM)\n                try:\n                    child.wait(timeout=20)\n                except subprocess.TimeoutExpired:\n                    os.killpg(child.pid,signal.SIGKILL)\n                    child.wait()\n\n\nif __name__==\'__main__\':\n    main()\n'
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,os,subprocess,sys,time
root=Path('/mnt/MiNas/GAN/research/N01/receipts/joint_response_01_20261020/recentered_derivative_completion_01')
root.mkdir(parents=True,exist_ok=True)
code=root/'SUPERVISOR_UNDER_TEST.py';code.write_text(source,encoding='utf-8')
test=root/'supervisor_io_fault_smoke_01';test.mkdir();(test/'resource_status.tmp').mkdir()
python='/home/rylan/projects/hpge-cpunet-validation-20261003/venv/bin/python'
command=[python,'-B',str(code),'--output',str(test),'--rss-limit-gib','1','--',python,'-B','-c','import time;time.sleep(30)']
started=time.monotonic();child=subprocess.run(command,capture_output=True,timeout=25,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',TMPDIR=str(root)))
assert child.returncode!=0 and b'IsADirectoryError' in child.stderr
launch=json.loads((test/'launch.json').read_bytes());pid=launch['child_pid'];assert not Path('/proc',str(pid)).exists()
record=dict(status='PASS_SUPERVISOR_IO_FAILURE_STOPS_OWNED_CHILD',UTC=datetime.now(timezone.utc).isoformat(),script_sha256=hashlib.sha256(source.encode()).hexdigest(),supervisor_exit_code=child.returncode,owned_child_pid=pid,owned_child_absent_after_failure=True,injected_error='resource_status.tmp is a directory',elapsed_seconds=time.monotonic()-started,new_scientific_calls=0,stdout=child.stdout.decode(),stderr=child.stderr.decode())
(test/'REVIEW.json').write_text(json.dumps(record,indent=2)+'\n',encoding='utf-8');print(json.dumps(record))
